'use strict';
let memberSelection=false;const selectedMembers=new Set();let queueOpen=false,toolsOpen=false;
function filteredMembers(){const q=$('#memberSearch').value.toLocaleLowerCase(),f=$('#memberFilter').value;return state.members.filter(m=>(m.name+' '+m.playerId).toLocaleLowerCase().includes(q)).filter(m=>f==='all'||f==='unassigned'&&!m.slot||String(m.trap)===f)}
renderMembers=function(){const ms=filteredMembers();$('#memberList').innerHTML=ms.map(m=>`<article class="officer-member"><button class="member-card ${memberSelection?'selectable':''}" data-officer-id="${esc(m.id)}" ${memberSelection?`aria-pressed="${selectedMembers.has(m.id)}"`:''}>${memberSelection?`<span class="selection-check" aria-hidden="true">${selectedMembers.has(m.id)?'✓':'○'}</span>`:`<span class="avatar">${esc(m.name.slice(0,1))}</span>`}<span><strong>${esc(m.name)}${m.locked?' · Locked':''}</strong><small>${esc(m.trap?'BT'+m.trap:'Other players')} · ${m.slot?'Placed · '+esc(slotLabel(m.slot)):'Not placed'}</small><span class="pill">${esc(frequencyBadge(m,m.trap))}</span>${Hive.assignmentNeedsReview(state,m)?'<span class="review-warning">Trap assignment needs review</span>':''}</span></button></article>`).join('')||'<div class="empty-state">No members match these filters.</div>';$$('[data-officer-id]').forEach(b=>b.onclick=()=>{if(memberSelection){selectedMembers.has(b.dataset.officerId)?selectedMembers.delete(b.dataset.officerId):selectedMembers.add(b.dataset.officerId);renderMembers();updateBulkBar()}else memberDetail(b.dataset.officerId)});updateBulkBar()};
function updateBulkBar(){for(const id of selectedMembers)if(!state.members.some(m=>m.id===id))selectedMembers.delete(id);$('#memberBulkBar').classList.toggle('hidden',!memberSelection||page!=='members');document.body.classList.toggle('selecting-members',memberSelection&&page==='members');$('#memberSelectionCount').textContent=`${selectedMembers.size} selected`;$('#memberSelectionSummary').textContent=memberSelection?`${filteredMembers().length} players shown. Changing filters keeps your selection.`:'';$('#selectMembers').textContent=memberSelection?'Selecting players':'Select players';$$('[data-bulk-group]').forEach(b=>b.disabled=!selectedMembers.size)}
function startMemberSelection(){memberSelection=true;selectedMembers.clear();renderMembers()}
$('#selectMembers').onclick=()=>{memberSelection?endMemberSelection():startMemberSelection()};
function endMemberSelection(){memberSelection=false;selectedMembers.clear();renderMembers()}
$('#cancelSelection').onclick=endMemberSelection;$('#clearSelection').onclick=()=>{selectedMembers.clear();renderMembers()};$('#selectAllShown').onclick=()=>{filteredMembers().forEach(m=>selectedMembers.add(m.id));renderMembers()};
$('#selectQueue').onclick=()=>{closeMapSheets();$('#memberFilter').value=String(state.operations.rosterGroup);$('#memberSearch').value=$('#queueSearch').value;navigate('members');startMemberSelection()};
$$('[data-bulk-group]').forEach(b=>b.onclick=()=>{const action=b.dataset.bulkGroup==='delete'?'delete':+b.dataset.bulkGroup,ids=[...selectedMembers],members=state.members.filter(m=>selectedMembers.has(m.id)&&(action==='delete'||m.trap!==action)),locks=members.filter(m=>Hive.memberHasLockedPlacement(state,m)),destination=action==='delete'?'Delete':action?'Move to BT'+action:'Move to Other players';openModal(`<div class="eyebrow">BULK MEMBER ACTION</div><h2>${destination} · ${members.length} players?</h2><p>${action==='delete'?'Delete these players and their city placements. Attendance history stays saved.':'Change group and unassign affected cities. Attendance history stays saved.'} Undo is available.</p>${locks.length?`<div class="notice">${locks.length} locked: ${locks.map(m=>esc(m.name)).join(', ')}</div><label>Locked cities<select id="bulkLockChoice"><option value="block">Choose how to handle locks…</option><option value="skip">Skip locked players</option><option value="unlock">Unlock and include locked players</option></select></label>`:''}<p id="bulkActionCount"></p><button class="primary ${action==='delete'?'danger':''}" id="applyMemberBulk" ${!members.length||locks.length?'disabled':''}>${destination}</button>`);const update=()=>{const choice=$('#bulkLockChoice')?.value||'block',count=members.length-(choice==='skip'?locks.length:0);$('#bulkActionCount').textContent=`${count} will change${choice==='skip'?' · '+locks.length+' locked players skipped':''}.`;$('#applyMemberBulk').disabled=!count||!!locks.length&&choice==='block';$('#applyMemberBulk').textContent=`${destination} · ${count}`};if(locks.length)$('#bulkLockChoice').onchange=update;update();$('#applyMemberBulk').onclick=()=>{try{const result=Hive.bulkMemberAction(state,ids,action,{locked:$('#bulkLockChoice')?.value||'block'});commit(()=>state=result.state);closeModal();memberSelection=false;selectedMembers.clear();render();toast(`${result.changed} ${result.changed===1?'member':'members'} updated${result.skipped?' · '+result.skipped+' locked skipped':''}. Undo is available.`)}catch(e){toast(e.message)}}});
openSlot=function(id){openAttendanceSlot(id)};
function trapDetails(id){const t=state.traps.find(t=>t.id===id),c=Hive.coord(state,{...t,trap:t.id}),other=3-id,hasOther=state.traps.some(t=>t.id===other);openModal(`<div class="eyebrow">BEAR TRAP ${id}</div><h2>Bear Trap ${id}</h2><p>X:${c.x} Y:${c.y}</p><button id="changeTrapNumber" ${readonly?'disabled':''}>Change trap number</button>`);$('#changeTrapNumber').onclick=()=>{const next=Hive.swapTrapNumbers(state,id),review=next.members.filter(m=>Hive.assignmentNeedsReview(next,m));openModal(`<div class="eyebrow">TRAP NUMBER PREVIEW</div><h2>${hasOther?'Swap BT1 and BT2?':'Change to BT'+other+'?'}</h2><p>Swap labels and city-space associations on this map. Positions, roster groups, schedules and attendance stay unchanged.</p><p>${review.length} ${review.length===1?'city assignment needs':'city assignments need'} review${review.length?': '+review.map(m=>esc(m.name)).join(', '):''}. Locked cities remain fixed. Move instructions will flag conflicting assignments. Undo is available.</p><button class="primary" id="applyTrapSwap">${hasOther?'Swap BT1 and BT2':'Change to BT'+other}</button>`);$('#applyTrapSwap').onclick=()=>{commit(()=>state=next);closeModal();activeTrap='all';render();fit();toast('Trap labels updated. Review affected assignments. Undo is available.')}}}
function closeMapSheets(){queueOpen=false;toolsOpen=false;updateMapSheets()}
function updateMapSheets(){$('#memberQueueSection').classList.toggle('phone-open',queueOpen);$('#mapTools').classList.toggle('phone-open',toolsOpen);$('#toggleQueue').setAttribute('aria-expanded',String(queueOpen));$('#toggleTools').setAttribute('aria-expanded',String(toolsOpen));$('#mapSheetBackdrop').classList.toggle('hidden',!queueOpen&&!toolsOpen)}
$('#toggleQueue').onclick=()=>{queueOpen=!queueOpen;toolsOpen=false;updateMapSheets()};$('#toggleTools').onclick=()=>{toolsOpen=!toolsOpen;queueOpen=false;updateMapSheets()};$('#mapSheetBackdrop').onclick=closeMapSheets;$('#closeQueueSheet').onclick=closeMapSheets;$('#closeToolsSheet').onclick=closeMapSheets;
$('#mapTools').addEventListener('click',e=>{if(e.target.closest('[data-tool],#loadLunBtn,#resetLayoutBtn,#undoBtn,#redoBtn'))closeMapSheets()});
const officerBaseQueue=renderQueue;renderQueue=function(){officerBaseQueue();$$('#queue [data-member]').forEach(b=>b.addEventListener('click',closeMapSheets))};$('#queueSearch').oninput=()=>renderQueue();
const officerBaseRender=render;render=function(){officerBaseRender();document.body.classList.toggle('map-view',page==='map');if(page==='map')$('#pageTitle').textContent='Hive map';updateBulkBar();const reviews=state.members.filter(m=>Hive.assignmentNeedsReview(state,m));$('#assignmentReviewNotice').classList.toggle('hidden',!reviews.length);$('#assignmentReviewNotice').textContent=reviews.length?`${reviews.length} ${reviews.length===1?'city assignment needs':'city assignments need'} review. City positions did not change.`:'';$$('#mapSvg [data-trap-id]').forEach(el=>{el.setAttribute('tabindex','0');el.setAttribute('role','button');el.setAttribute('aria-label','Bear Trap '+el.dataset.trapId);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();trapDetails(+el.dataset.trapId)}}});if(page!=='map'&&(queueOpen||toolsOpen))closeMapSheets()};
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeMapSheets()});
render();

function updateVisualHeight(){document.documentElement.style.setProperty('--visual-height',(window.visualViewport?.height||window.innerHeight)+'px')}
window.visualViewport?.addEventListener('resize',updateVisualHeight);if(document.documentElement)updateVisualHeight();
const officerBaseMap=renderMap;renderMap=function(){officerBaseMap();$$('#mapSvg [data-trap-id]').forEach(el=>{el.setAttribute('tabindex','0');el.setAttribute('role','button');el.setAttribute('aria-label','Bear Trap '+el.dataset.trapId);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();trapDetails(+el.dataset.trapId)}}});for(const m of state.members.filter(m=>Hive.assignmentNeedsReview(state,m))){const el=$$('#mapSvg [data-slot]').find(el=>el.dataset.slot===m.slot)?.querySelector('polygon');if(el){el.setAttribute('stroke','#a35337');el.setAttribute('stroke-width','3')}}};
renderMap();

function sizePhoneMap(){if(page!=='map'||!window.matchMedia?.('(max-width:720px)').matches)return;const el=$('#mapViewport'),top=el.getBoundingClientRect().top+window.scrollY,height=Math.round(Math.max(220,Math.min(500,(window.visualViewport?.height||window.innerHeight)-88-top)));if(el.style.getPropertyValue('--phone-map-height')!==height+'px'){const before=el.getBoundingClientRect();el.style.setProperty('--phone-map-height',height+'px');const after=el.getBoundingClientRect();camera.x+=(after.width-before.width)/2;camera.y+=(after.height-before.height)/2;renderMap()}}
const phoneSizedRender=render;render=function(){phoneSizedRender();sizePhoneMap()};window.addEventListener('resize',sizePhoneMap);window.visualViewport?.addEventListener('resize',sizePhoneMap);sizePhoneMap();
